type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  const escape = (s: string): string =>
    s
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#39;");
  const styles: string[] = Array.from({ length: d.text.length }, (_, i) =>
    ["b", "i"]
      .filter((s) => d.ranges.some((r: any[]) => r[2] === s && r[0] <= i && i < r[1]))
      .join(""),
  );
  let out = "";
  for (let i = 0; i < styles.length; ) {
    let j = i + 1;
    while (j < styles.length && styles[j] === styles[i]) j++;
    let text = escape(d.text.slice(i, j));
    for (const s of [...styles[i]].reverse()) text = "<" + s + ">" + text + "</" + s + ">";
    out += text;
    i = j;
  }
  return out;
}
